/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 *
 * Field semantics (see docs/API.md and docs/CHANGELOG.md — newest entry wins):
 * - `amount` is an integer in cents; the report renders `amount / 100` with
 *   exactly two decimal places (v2.0).
 * - `discount` is the final discounted amount in cents; it is rendered as-is
 *   (`discount / 100` with two decimals) and must never be computed from a
 *   rate (v2.1).
 * - `created` is rendered from `createdAt` (UTC epoch milliseconds) as an
 *   ISO-8601 timestamp with an explicit `+08:00` offset (v2.3).
 */

const HOUR_MS = 60 * 60 * 1000
const TZ_OFFSET_MS = 8 * HOUR_MS

/** Render an integer amount in cents with exactly two decimal places. */
function formatCents(cents) {
  const value = Number(cents)
  const safe = Number.isFinite(value) ? value : 0
  return (safe / 100).toFixed(2)
}

/** Render a UTC epoch-millisecond timestamp in the +08:00 timezone. */
function formatCreated(ms) {
  const value = Number(ms)
  const safe = Number.isFinite(value) ? value : 0
  const date = new Date(safe + TZ_OFFSET_MS)
  const pad = (n, width = 2) => String(n).padStart(width, '0')
  const ymd =
    `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`
  const hms =
    `${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}:${pad(date.getUTCSeconds())}`
  return `${ymd}T${hms}.${pad(date.getUTCMilliseconds(), 3)}+08:00`
}

export function formatReport(records) {
  const lines = ['id|name|amount|discount|created']
  for (const record of records) {
    const amount = formatCents(record.amount)
    const discount = formatCents(record.discount)
    const created = formatCreated(record.createdAt)
    lines.push(`${record.id}|${record.name ?? ''}|${amount}|${discount}|${created}`)
  }
  return lines
}
